-- ---------------------------------------------------------------------
-- Administrator accounts (Table 4.7)
--
-- Password hashes are generated by pgcrypto's crypt() with a blowfish
-- salt, producing a standard bcrypt hash that Python's `bcrypt` library
-- verifies directly. This avoids having to run Python before the backend
-- exists in Phase 2.
--
-- Development credentials:
--   officer@ncsm.org.my    / ScopeDev2026!
--   researcher@ncsm.org.my / ScopeDev2026!
-- ---------------------------------------------------------------------
INSERT INTO admin_user (email, password_hash, full_name, organisation, role) VALUES
    ('officer@ncsm.org.my',
     crypt('ScopeDev2026!', gen_salt('bf', 12)),
     'Enforcement Officer (Dev)',
     'NCSM',
     'OFFICER'),
    ('researcher@ncsm.org.my',
     crypt('ScopeDev2026!', gen_salt('bf', 12)),
     'Research Team Officer (Dev)',
     'NCSM',
     'RESEARCHER');


